<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- relic choice grid from towerSystem */
  import { onDestroy } from 'svelte';
  import {
    setRelicModalShow,
    setRelicModalClose,
    type RelicModalPayload,
  } from '../bridge/relicModalBridge.js';

  let visible = $state(false);
  let payload = $state<RelicModalPayload | null>(null);

  function show(data: RelicModalPayload) {
    payload = data;
    visible = true;
    const modal = document.getElementById('relicModal');
    modal?.classList.add('show');
    if (data.passive) {
      modal?.classList.add('relic-modal-passive');
      modal?.setAttribute('aria-modal', 'false');
    } else {
      modal?.classList.remove('relic-modal-passive');
      modal?.setAttribute('aria-modal', 'true');
    }
  }

  function close() {
    visible = false;
    payload = null;
    const modal = document.getElementById('relicModal');
    modal?.classList.remove('show', 'relic-modal-passive');
    modal?.setAttribute('aria-modal', 'true');
  }

  setRelicModalShow(show);
  setRelicModalClose(close);
  onDestroy(() => {
    setRelicModalShow(() => {});
    setRelicModalClose(() => {});
  });
</script>

<div class="stats-content" style="text-align: center;" data-action="stopPropagation" data-action-stop>
  <div class="stats-header">
    <h2 id="relicRewardTitleLabel">Recompense d'Etage</h2>
  </div>
  {#if visible && payload}
    <p id="relicRewardBodyLabel" style="margin-bottom: 20px;">{payload.bodyLabel}</p>
    <div
      id="relicOptionsGrid"
      style="display: flex; justify-content: center; gap: 15px; flex-wrap: wrap; margin-top: 15px;"
    >
      {@html payload.gridHtml}
    </div>
  {/if}
</div>
